from .errors import MiniCoreRuntimeError
from .ast_nodes import (
    AST_INT,
    AST_BOOL,
    AST_VAR,
    AST_LAM,
    AST_APP,
    AST_BINOP,
    AST_IF,
    AST_ANNO,
    AST_LET,
)

IR_CONST = 0
IR_LOCAL = 1
IR_UPVAL = 2
IR_LAM = 3
IR_APP = 4
IR_BINOP = 5
IR_IF = 6
IR_LET = 7
IR_LETREC = 8

OP_ADD = 0
OP_SUB = 1
OP_MUL = 2
OP_DIV = 3
OP_MOD = 4
OP_EQ = 5
OP_LT = 6

BIN_OP_MAP = {
    "+": OP_ADD,
    "-": OP_SUB,
    "*": OP_MUL,
    "//": OP_DIV,
    "%": OP_MOD,
    "==": OP_EQ,
    "<": OP_LT,
}

C_LAM_DONE = 0
C_APP_DONE = 1
C_BIN_DONE = 2
C_IF_DONE = 3
C_LET_AFTER_RHS = 4
C_LET_DONE = 5
C_LETREC_DONE = 6

K_IF = 0
K_LET = 1
K_BIN1 = 2
K_BIN2 = 3
K_APP_FN = 4
K_APP_ARGS = 5
K_APP_OVER = 6


class FuncBuilder:
    __slots__ = ("num_locals", "upval_map", "upval_list")

    def __init__(self, num_locals: int):
        self.num_locals = num_locals
        self.upval_map: dict[tuple[bool, int], int] = {}
        self.upval_list: list[tuple[bool, int]] = []

    def alloc_local(self) -> int:
        s = self.num_locals
        self.num_locals = s + 1
        return s


class Closure:
    __slots__ = ("arity", "num_locals", "body", "upvals", "applied")

    def __init__(self, arity: int, num_locals: int, body, upvals, applied=()):
        self.arity = arity
        self.num_locals = num_locals
        self.body = body
        self.upvals = upvals
        self.applied = applied


def compile_program(ast):
    func_stack = [FuncBuilder(0)]
    var_env: dict[str, tuple[int, int]] = {}
    work = [ast]
    out = []

    while work:
        item = work.pop()
        if isinstance(item, tuple):
            ctag = item[0]
            if ctag == C_LAM_DONE:
                _, saved, arity = item
                for pname, prev in reversed(saved):
                    if prev is None:
                        del var_env[pname]
                    else:
                        var_env[pname] = prev
                fb = func_stack.pop()
                body_ir = out.pop()
                out.append((IR_LAM, (arity, fb.num_locals, tuple(fb.upval_list), body_ir)))
            elif ctag == C_APP_DONE:
                m = item[1]
                args_ir = [None] * m
                for i in range(m - 1, -1, -1):
                    args_ir[i] = out.pop()
                fn_ir = out.pop()
                out.append((IR_APP, fn_ir, tuple(args_ir)))
            elif ctag == C_BIN_DONE:
                r_ir = out.pop()
                l_ir = out.pop()
                out.append((IR_BINOP, item[1], l_ir, r_ir))
            elif ctag == C_IF_DONE:
                else_ir = out.pop()
                then_ir = out.pop()
                cond_ir = out.pop()
                out.append((IR_IF, cond_ir, then_ir, else_ir))
            elif ctag == C_LET_AFTER_RHS:
                _, name, body = item
                slot = func_stack[-1].alloc_local()
                d = len(func_stack) - 1
                prev = var_env.get(name)
                var_env[name] = (d, slot)
                work.append((C_LET_DONE, name, prev, slot))
                work.append(body)
            elif ctag == C_LET_DONE:
                _, name, prev, slot = item
                if prev is None:
                    del var_env[name]
                else:
                    var_env[name] = prev
                body_ir = out.pop()
                rhs_ir = out.pop()
                out.append((IR_LET, slot, rhs_ir, body_ir))
            else:  # C_LETREC_DONE
                _, name, prev, slot = item
                if prev is None:
                    del var_env[name]
                else:
                    var_env[name] = prev
                body_ir = out.pop()
                lam_ir = out.pop()
                out.append((IR_LETREC, slot, lam_ir[1], body_ir))
        else:
            ntag = item.tag
            if ntag == AST_INT:
                out.append((IR_CONST, int(item.raw)))
            elif ntag == AST_BOOL:
                out.append((IR_CONST, item.val))
            elif ntag == AST_VAR:
                def_depth, slot = var_env[item.name]
                cur_depth = len(func_stack) - 1
                if def_depth == cur_depth:
                    out.append((IR_LOCAL, slot))
                else:
                    idx = slot
                    for k in range(def_depth + 1, cur_depth + 1):
                        src = (k == def_depth + 1, idx)
                        fb = func_stack[k]
                        u = fb.upval_map.get(src)
                        if u is None:
                            u = len(fb.upval_list)
                            fb.upval_map[src] = u
                            fb.upval_list.append(src)
                        idx = u
                    out.append((IR_UPVAL, idx))
            elif ntag == AST_ANNO:
                work.append(item.expr)
            elif ntag == AST_LAM:
                params = []
                cur = item
                while cur.tag == AST_LAM:
                    params.append(cur.param)
                    cur = cur.body
                arity = len(params)
                fb = FuncBuilder(arity)
                func_stack.append(fb)
                d = len(func_stack) - 1
                saved = []
                for slot_i, pname in enumerate(params):
                    saved.append((pname, var_env.get(pname)))
                    var_env[pname] = (d, slot_i)
                work.append((C_LAM_DONE, saved, arity))
                work.append(cur)
            elif ntag == AST_APP:
                args = []
                cur = item
                while cur.tag == AST_APP:
                    args.append(cur.arg)
                    cur = cur.fn
                args.reverse()
                work.append((C_APP_DONE, len(args)))
                for a in reversed(args):
                    work.append(a)
                work.append(cur)
            elif ntag == AST_BINOP:
                work.append((C_BIN_DONE, BIN_OP_MAP[item.op]))
                work.append(item.right)
                work.append(item.left)
            elif ntag == AST_IF:
                work.append((C_IF_DONE,))
                work.append(item.else_br)
                work.append(item.then_br)
                work.append(item.cond)
            elif ntag == AST_LET:
                work.append((C_LET_AFTER_RHS, item.name, item.body))
                work.append(item.rhs)
            else:  # AST_LETREC
                slot = func_stack[-1].alloc_local()
                d = len(func_stack) - 1
                prev = var_env.get(item.name)
                var_env[item.name] = (d, slot)
                work.append((C_LETREC_DONE, item.name, prev, slot))
                work.append(item.body)
                work.append(item.rhs)

    return func_stack[0].num_locals, out[0]


def evaluate(ast):
    top_locals, expr = compile_program(ast)
    cur_locals = [None] * top_locals if top_locals else []
    cur_upvals = ()
    stack = []
    push = stack.append
    pop = stack.pop
    evaluating = True
    val = None

    while True:
        if evaluating:
            etag = expr[0]
            if etag == IR_CONST:
                val = expr[1]
                evaluating = False
            elif etag == IR_LOCAL:
                val = cur_locals[expr[1]]
                evaluating = False
            elif etag == IR_UPVAL:
                val = cur_upvals[expr[1]]
                evaluating = False
            elif etag == IR_BINOP:
                _, op, l_ir, r_ir = expr
                ltag = l_ir[0]
                if ltag <= 2:
                    v1 = (
                        l_ir[1]
                        if ltag == 0
                        else (cur_locals[l_ir[1]] if ltag == 1 else cur_upvals[l_ir[1]])
                    )
                    rtag = r_ir[0]
                    if rtag <= 2:
                        v2 = (
                            r_ir[1]
                            if rtag == 0
                            else (cur_locals[r_ir[1]] if rtag == 1 else cur_upvals[r_ir[1]])
                        )
                        if op == OP_ADD:
                            val = v1 + v2
                        elif op == OP_SUB:
                            val = v1 - v2
                        elif op == OP_MUL:
                            val = v1 * v2
                        elif op == OP_EQ:
                            val = v1 == v2
                        elif op == OP_LT:
                            val = v1 < v2
                        elif op == OP_DIV:
                            if v2 == 0:
                                raise MiniCoreRuntimeError("division by zero")
                            val = v1 // v2
                        else:
                            if v2 == 0:
                                raise MiniCoreRuntimeError("modulo by zero")
                            val = v1 % v2
                        evaluating = False
                    else:
                        push((K_BIN2, op, v1))
                        expr = r_ir
                else:
                    push((K_BIN1, op, r_ir, cur_locals, cur_upvals))
                    expr = l_ir
            elif etag == IR_IF:
                _, cond_ir, then_ir, else_ir = expr
                ctag = cond_ir[0]
                if ctag <= 2:
                    cval = (
                        cond_ir[1]
                        if ctag == 0
                        else (cur_locals[cond_ir[1]] if ctag == 1 else cur_upvals[cond_ir[1]])
                    )
                    expr = then_ir if cval else else_ir
                else:
                    push((K_IF, then_ir, else_ir, cur_locals, cur_upvals))
                    expr = cond_ir
            elif etag == IR_APP:
                _, fn_ir, args_tuple = expr
                ftag = fn_ir[0]
                if ftag <= 2:
                    clos = (
                        fn_ir[1]
                        if ftag == 0
                        else (cur_locals[fn_ir[1]] if ftag == 1 else cur_upvals[fn_ir[1]])
                    )
                    arity = clos.arity
                    m = len(args_tuple)
                    # Fast path: 1-arg unapplied closure
                    if m == 1 and arity == 1 and not clos.applied:
                        a0 = args_tuple[0]
                        atag = a0[0]
                        if atag <= 2:
                            v0 = (
                                a0[1]
                                if atag == 0
                                else (cur_locals[a0[1]] if atag == 1 else cur_upvals[a0[1]])
                            )
                            nl = clos.num_locals
                            if nl == 1:
                                cur_locals = [v0]
                            else:
                                cur_locals = [None] * nl
                                cur_locals[0] = v0
                            cur_upvals = clos.upvals
                            expr = clos.body
                            continue
                    evaled = list(clos.applied) if clos.applied else []
                    idx = 0
                    paused = False
                    while len(evaled) < arity and idx < m:
                        a_ir = args_tuple[idx]
                        idx += 1
                        atag = a_ir[0]
                        if atag <= 2:
                            evaled.append(
                                a_ir[1]
                                if atag == 0
                                else (cur_locals[a_ir[1]] if atag == 1 else cur_upvals[a_ir[1]])
                            )
                        else:
                            push((K_APP_ARGS, clos, args_tuple, idx, evaled, cur_locals, cur_upvals))
                            expr = a_ir
                            paused = True
                            break
                    if not paused:
                        if len(evaled) < arity:
                            val = Closure(
                                arity, clos.num_locals, clos.body, clos.upvals, tuple(evaled)
                            )
                            evaluating = False
                        else:
                            if idx < m:
                                push((K_APP_OVER, args_tuple, idx, cur_locals, cur_upvals))
                            nl = clos.num_locals
                            if nl == arity:
                                cur_locals = evaled
                            else:
                                cur_locals = evaled + [None] * (nl - arity)
                            cur_upvals = clos.upvals
                            expr = clos.body
                else:
                    push((K_APP_FN, args_tuple, cur_locals, cur_upvals))
                    expr = fn_ir
            elif etag == IR_LAM:
                arity, num_loc, upval_srcs, body_ir = expr[1]
                if upval_srcs:
                    uv = [
                        cur_locals[idx] if is_loc else cur_upvals[idx]
                        for is_loc, idx in upval_srcs
                    ]
                else:
                    uv = ()
                val = Closure(arity, num_loc, body_ir, uv)
                evaluating = False
            elif etag == IR_LET:
                _, slot, rhs_ir, body_ir = expr
                rtag = rhs_ir[0]
                if rtag <= 2:
                    rval = (
                        rhs_ir[1]
                        if rtag == 0
                        else (cur_locals[rhs_ir[1]] if rtag == 1 else cur_upvals[rhs_ir[1]])
                    )
                    cur_locals[slot] = rval
                    expr = body_ir
                else:
                    push((K_LET, slot, body_ir, cur_locals, cur_upvals))
                    expr = rhs_ir
            else:  # IR_LETREC
                _, slot, proto, body_ir = expr
                arity, num_loc, upval_srcs, fn_body = proto
                if upval_srcs:
                    uv = [None] * len(upval_srcs)
                    clos = Closure(arity, num_loc, fn_body, uv)
                    cur_locals[slot] = clos
                    for i, (is_loc, idx) in enumerate(upval_srcs):
                        uv[i] = cur_locals[idx] if is_loc else cur_upvals[idx]
                else:
                    clos = Closure(arity, num_loc, fn_body, ())
                    cur_locals[slot] = clos
                expr = body_ir
        else:
            if not stack:
                return val
            frame = pop()
            ktag = frame[0]
            if ktag == K_IF:
                _, then_ir, else_ir, cur_locals, cur_upvals = frame
                expr = then_ir if val else else_ir
                evaluating = True
            elif ktag == K_BIN2:
                op = frame[1]
                v1 = frame[2]
                v2 = val
                if op == OP_ADD:
                    val = v1 + v2
                elif op == OP_SUB:
                    val = v1 - v2
                elif op == OP_MUL:
                    val = v1 * v2
                elif op == OP_EQ:
                    val = v1 == v2
                elif op == OP_LT:
                    val = v1 < v2
                elif op == OP_DIV:
                    if v2 == 0:
                        raise MiniCoreRuntimeError("division by zero")
                    val = v1 // v2
                else:
                    if v2 == 0:
                        raise MiniCoreRuntimeError("modulo by zero")
                    val = v1 % v2
            elif ktag == K_APP_ARGS:
                _, clos, args_tuple, idx, evaled, cur_locals, cur_upvals = frame
                evaled.append(val)
                arity = clos.arity
                m = len(args_tuple)
                paused = False
                while len(evaled) < arity and idx < m:
                    a_ir = args_tuple[idx]
                    idx += 1
                    atag = a_ir[0]
                    if atag <= 2:
                        evaled.append(
                            a_ir[1]
                            if atag == 0
                            else (cur_locals[a_ir[1]] if atag == 1 else cur_upvals[a_ir[1]])
                        )
                    else:
                        push((K_APP_ARGS, clos, args_tuple, idx, evaled, cur_locals, cur_upvals))
                        expr = a_ir
                        evaluating = True
                        paused = True
                        break
                if not paused:
                    if len(evaled) < arity:
                        val = Closure(
                            arity, clos.num_locals, clos.body, clos.upvals, tuple(evaled)
                        )
                    else:
                        if idx < m:
                            push((K_APP_OVER, args_tuple, idx, cur_locals, cur_upvals))
                        nl = clos.num_locals
                        if nl == arity:
                            cur_locals = evaled
                        else:
                            cur_locals = evaled + [None] * (nl - arity)
                        cur_upvals = clos.upvals
                        expr = clos.body
                        evaluating = True
            elif ktag == K_LET:
                _, slot, body_ir, cur_locals, cur_upvals = frame
                cur_locals[slot] = val
                expr = body_ir
                evaluating = True
            elif ktag == K_BIN1:
                _, op, r_ir, cur_locals, cur_upvals = frame
                rtag = r_ir[0]
                if rtag <= 2:
                    v2 = (
                        r_ir[1]
                        if rtag == 0
                        else (cur_locals[r_ir[1]] if rtag == 1 else cur_upvals[r_ir[1]])
                    )
                    v1 = val
                    if op == OP_ADD:
                        val = v1 + v2
                    elif op == OP_SUB:
                        val = v1 - v2
                    elif op == OP_MUL:
                        val = v1 * v2
                    elif op == OP_EQ:
                        val = v1 == v2
                    elif op == OP_LT:
                        val = v1 < v2
                    elif op == OP_DIV:
                        if v2 == 0:
                            raise MiniCoreRuntimeError("division by zero")
                        val = v1 // v2
                    else:
                        if v2 == 0:
                            raise MiniCoreRuntimeError("modulo by zero")
                        val = v1 % v2
                else:
                    push((K_BIN2, op, val))
                    expr = r_ir
                    evaluating = True
            else:  # K_APP_FN or K_APP_OVER
                if ktag == K_APP_FN:
                    _, args_tuple, cur_locals, cur_upvals = frame
                    idx = 0
                else:
                    _, args_tuple, idx, cur_locals, cur_upvals = frame
                clos = val
                arity = clos.arity
                m = len(args_tuple)
                evaled = list(clos.applied) if clos.applied else []
                paused = False
                while len(evaled) < arity and idx < m:
                    a_ir = args_tuple[idx]
                    idx += 1
                    atag = a_ir[0]
                    if atag <= 2:
                        evaled.append(
                            a_ir[1]
                            if atag == 0
                            else (cur_locals[a_ir[1]] if atag == 1 else cur_upvals[a_ir[1]])
                        )
                    else:
                        push((K_APP_ARGS, clos, args_tuple, idx, evaled, cur_locals, cur_upvals))
                        expr = a_ir
                        evaluating = True
                        paused = True
                        break
                if not paused:
                    if len(evaled) < arity:
                        val = Closure(
                            arity, clos.num_locals, clos.body, clos.upvals, tuple(evaled)
                        )
                    else:
                        if idx < m:
                            push((K_APP_OVER, args_tuple, idx, cur_locals, cur_upvals))
                        nl = clos.num_locals
                        if nl == arity:
                            cur_locals = evaled
                        else:
                            cur_locals = evaled + [None] * (nl - arity)
                        cur_upvals = clos.upvals
                        expr = clos.body
                        evaluating = True


