def ast_to_sexpr(node):
    from mc.ast_nodes import (
        TY_INT,
        TY_BOOL,
        AST_INT,
        AST_BOOL,
        AST_VAR,
        AST_LAM,
        AST_APP,
        AST_BINOP,
        AST_IF,
        AST_ANNO,
        AST_LET,
    )

    def ty_s(t):
        if t.tag == TY_INT:
            return "Int"
        if t.tag == TY_BOOL:
            return "Bool"
        return ("->", ty_s(t.left), ty_s(t.right))

    ntag = node.tag
    if ntag == AST_INT:
        return ("int", node.raw)
    if ntag == AST_BOOL:
        return ("bool", node.val)
    if ntag == AST_VAR:
        return ("var", node.name)
    if ntag == AST_LAM:
        return ("lam", node.param, ast_to_sexpr(node.body))
    if ntag == AST_APP:
        return ("app", ast_to_sexpr(node.fn), ast_to_sexpr(node.arg))
    if ntag == AST_BINOP:
        return ("bin", node.op, ast_to_sexpr(node.left), ast_to_sexpr(node.right))
    if ntag == AST_IF:
        return ("if", ast_to_sexpr(node.cond), ast_to_sexpr(node.then_br), ast_to_sexpr(node.else_br))
    if ntag == AST_ANNO:
        return ("anno", ast_to_sexpr(node.expr), ty_s(node.ty))
    if ntag == AST_LET:
        return (
            "let",
            node.name,
            None if node.ty is None else ty_s(node.ty),
            ast_to_sexpr(node.rhs),
            ast_to_sexpr(node.body),
        )
    return (
        "letrec",
        node.name,
        ty_s(node.ty),
        ast_to_sexpr(node.rhs),
        ast_to_sexpr(node.body),
    )


def ref_parse_ebnf(tokens):
    # Direct recursive-descent transcription of §3 EBNF + let rec lambda rule
    from mc.lexer import (
        TOK_EOF,
        TOK_INT,
        TOK_IDENT,
        TOK_TRUE,
        TOK_FALSE,
        TOK_TINT,
        TOK_TBOOL,
        TOK_LET,
        TOK_REC,
        TOK_IN,
        TOK_IF,
        TOK_THEN,
        TOK_ELSE,
        TOK_LPAREN,
        TOK_RPAREN,
        TOK_ARROW,
        TOK_SLASH,
        TOK_PLUS,
        TOK_MINUS,
        TOK_STAR,
        TOK_FDIV,
        TOK_MOD,
        TOK_EQEQ,
        TOK_LT,
        TOK_EQ,
        TOK_COLON,
    )

    p = [0]

    def peek():
        return tokens[p[0]]

    def eat(k):
        if tokens[p[0]][0] != k:
            raise ValueError()
        val = tokens[p[0]][1]
        p[0] += 1
        return val

    def p_type():
        lhs = p_tatom()
        if peek()[0] == TOK_ARROW:
            eat(TOK_ARROW)
            rhs = p_type()
            return ("->", lhs, rhs)
        return lhs

    def p_tatom():
        tk = peek()[0]
        if tk == TOK_TINT:
            eat(TOK_TINT)
            return "Int"
        if tk == TOK_TBOOL:
            eat(TOK_TBOOL)
            return "Bool"
        if tk == TOK_LPAREN:
            eat(TOK_LPAREN)
            t = p_type()
            eat(TOK_RPAREN)
            return t
        raise ValueError()

    def p_expr():
        tk = peek()[0]
        if tk == TOK_SLASH:
            eat(TOK_SLASH)
            x = eat(TOK_IDENT)
            eat(TOK_ARROW)
            return ("lam", x, p_expr())
        if tk == TOK_LET:
            eat(TOK_LET)
            if peek()[0] == TOK_REC:
                eat(TOK_REC)
                f = eat(TOK_IDENT)
                eat(TOK_COLON)
                ty = p_type()
                eat(TOK_EQ)
                e1 = p_expr()
                if e1[0] != "lam":
                    raise ValueError()
                eat(TOK_IN)
                e2 = p_expr()
                return ("letrec", f, ty, e1, e2)
            x = eat(TOK_IDENT)
            ty = None
            if peek()[0] == TOK_COLON:
                eat(TOK_COLON)
                ty = p_type()
            eat(TOK_EQ)
            e1 = p_expr()
            eat(TOK_IN)
            e2 = p_expr()
            return ("let", x, ty, e1, e2)
        if tk == TOK_IF:
            eat(TOK_IF)
            c = p_expr()
            eat(TOK_THEN)
            t = p_expr()
            eat(TOK_ELSE)
            e = p_expr()
            return ("if", c, t, e)
        return p_cmp()

    def p_cmp():
        lhs = p_add()
        if peek()[0] in (TOK_EQEQ, TOK_LT):
            op = eat(peek()[0])
            rhs = p_add()
            return ("bin", op, lhs, rhs)
        return lhs

    def p_add():
        lhs = p_mul()
        while peek()[0] in (TOK_PLUS, TOK_MINUS):
            op = eat(peek()[0])
            lhs = ("bin", op, lhs, p_mul())
        return lhs

    def p_mul():
        lhs = p_app()
        while peek()[0] in (TOK_STAR, TOK_FDIV, TOK_MOD):
            op = eat(peek()[0])
            lhs = ("bin", op, lhs, p_app())
        return lhs

    def p_app():
        lhs = p_atom()
        while peek()[0] in (TOK_IDENT, TOK_INT, TOK_TRUE, TOK_FALSE, TOK_LPAREN):
            lhs = ("app", lhs, p_atom())
        return lhs

    def p_atom():
        tk, tv = peek()
        if tk == TOK_IDENT:
            eat(TOK_IDENT)
            return ("var", tv)
        if tk == TOK_INT:
            eat(TOK_INT)
            return ("int", tv)
        if tk == TOK_TRUE:
            eat(TOK_TRUE)
            return ("bool", True)
        if tk == TOK_FALSE:
            eat(TOK_FALSE)
            return ("bool", False)
        if tk == TOK_LPAREN:
            eat(TOK_LPAREN)
            e = p_expr()
            if peek()[0] == TOK_COLON:
                eat(TOK_COLON)
                ty = p_type()
                eat(TOK_RPAREN)
                return ("anno", e, ty)
            eat(TOK_RPAREN)
            return e
        raise ValueError()

    res = p_expr()
    eat(TOK_EOF)
    return res


def test_parser_ebnf_fuzz():
    from mc.errors import MiniCoreParseError
    from mc.lexer import tokenize
    from mc.parser import parse

    rng = random.Random(987654321)
    fragments = [
        "x", "y", "0", "42", "True", "False",
        "+", "-", "*", "//", "%", "==", "<",
        "(", ")", ":", "->", "/", "=",
        "let", "rec", "in", "if", "then", "else",
        "Int", "Bool",
    ]

    def gen_unparen(depth):
        if depth <= 0:
            return rng.choice(["x", "1", "2", "True", "False"])
        r = rng.randint(0, 11)
        if r == 0:
            return f"/x -> {gen_unparen(depth - 1)}"
        if r == 1:
            return f"let x = {gen_unparen(depth - 1)} in {gen_unparen(depth - 1)}"
        if r == 2:
            return f"let x : Int -> Int = {gen_unparen(depth - 1)} in {gen_unparen(depth - 1)}"
        if r == 3:
            rhs = rng.choice([f"/y -> {gen_unparen(depth - 1)}", f"(/y -> {gen_unparen(depth - 1)})", gen_unparen(depth - 1)])
            return f"let rec f : Int -> Int = {rhs} in {gen_unparen(depth - 1)}"
        if r == 4:
            return f"if {gen_unparen(depth - 1)} then {gen_unparen(depth - 1)} else {gen_unparen(depth - 1)}"
        if r == 5:
            op = rng.choice(["+", "-", "*", "//", "%", "==", "<"])
            return f"{gen_unparen(depth - 1)} {op} {gen_unparen(depth - 1)}"
        if r == 6:
            return f"{gen_unparen(depth - 1)} {gen_unparen(depth - 1)}"
        if r == 7:
            return f"({gen_unparen(depth - 1)})"
        if r == 8:
            return f"({gen_unparen(depth - 1)} : Int -> Bool -> Int)"
        if r == 9:
            return " ".join(rng.choice(fragments) for _ in range(rng.randint(1, 8)))
        return rng.choice(["x", "7", "True"])

    ok_cnt = 0
    err_cnt = 0
    for i in range(3000):
        src = gen_unparen(rng.randint(1, 4))
        toks = tokenize(src.encode("ascii"))
        try:
            ref_ast = ref_parse_ebnf(toks)
            ref_ok = True
        except ValueError:
            ref_ast = None
            ref_ok = False
        try:
            our_ast = ast_to_sexpr(parse(toks))
            our_ok = True
        except MiniCoreParseError:
            our_ast = None
            our_ok = False
        if our_ok != ref_ok or (our_ok and our_ast != ref_ast):
            raise AssertionError(
                f"Parser mismatch #{i}:\n  src={src!r}\n  our=({our_ok}, {our_ast})\n  ref=({ref_ok}, {ref_ast})"
            )
        if our_ok:
            ok_cnt += 1
        else:
            err_cnt += 1
    print(f"  [PASS] 3,000 EBNF parser differential tests (ok={ok_cnt}, ParseError={err_cnt})")


def test_well_typed_higher_order_fuzz():
    from mc.lexer import tokenize
    from mc.parser import parse

    rng = random.Random(135792468)

    def ty_str(t):
        if t == "Int" or t == "Bool":
            return t
        l, r = t
        ls = f"({ty_str(l)})" if isinstance(l, tuple) else ty_str(l)
        return f"{ls} -> {ty_str(r)}"

    def rand_ty(depth=2):
        if depth <= 0 or rng.random() < 0.55:
            return rng.choice(["Int", "Bool"])
        return (rand_ty(depth - 1), rand_ty(depth - 1))

    counter = [0]

    def fresh_name(prefix="v"):
        counter[0] += 1
        return f"{prefix}{counter[0] % 5}"  # deliberate shadowing across 5 names!

    def gen_typed(target_ty, env, depth):
        # env: dict[name -> ty]
        matching = [k for k, v in env.items() if v == target_ty]
        if depth <= 0:
            if matching and rng.random() < 0.6:
                return rng.choice(matching)
            if target_ty == "Int":
                n = rng.randint(-8, 8)
                return str(n) if n >= 0 else f"(0 - {-n})"
            if target_ty == "Bool":
                return rng.choice(["True", "False"])
            p = fresh_name("p")
            e2 = dict(env)
            e2[p] = target_ty[0]
            return f"(/{p} -> {gen_typed(target_ty[1], e2, 0)})"

        choice = rng.randint(0, 7)
        if choice == 0 and matching:
            return rng.choice(matching)
        if choice == 1 and isinstance(target_ty, tuple):
            # Multi-arg or 1-arg lambda
            p = fresh_name("p")
            e2 = dict(env)
            e2[p] = target_ty[0]
            return f"(/{p} -> {gen_typed(target_ty[1], e2, depth - 1)})"
        if choice == 2:
            # if-then-else
            c = gen_typed("Bool", env, depth - 1)
            t = gen_typed(target_ty, env, depth - 1)
            f = gen_typed(target_ty, env, depth - 1)
            return f"(if {c} then {t} else {f})"
        if choice == 3:
            # let (annotated or unannotated)
            vt = rand_ty(1)
            vn = fresh_name("x")
            rhs = gen_typed(vt, env, depth - 1)
            e2 = dict(env)
            e2[vn] = vt
            ann = f" : {ty_str(vt)}" if rng.random() < 0.5 else ""
            return f"(let {vn}{ann} = {rhs} in {gen_typed(target_ty, e2, depth - 1)})"
        if choice == 4:
            # application (including curried/partial/over-application!)
            arg_ty = rand_ty(1)
            fn_expr = gen_typed((arg_ty, target_ty), env, depth - 1)
            arg_expr = gen_typed(arg_ty, env, depth - 1)
            return f"({fn_expr} {arg_expr})"
        if choice == 5 and target_ty == "Int":
            op = rng.choice(["+", "-", "*", "//", "%"])
            return f"({gen_typed('Int', env, depth - 1)} {op} {gen_typed('Int', env, depth - 1)})"
        if choice == 6 and target_ty == "Bool":
            op = rng.choice(["==", "<"])
            return f"({gen_typed('Int', env, depth - 1)} {op} {gen_typed('Int', env, depth - 1)})"
        if choice == 7:
            # let rec with guaranteed termination via fuel argument
            fn = fresh_name("r")
            ret_t = rand_ty(1)
            rec_t = ("Int", ret_t)
            e_rec = dict(env)
            e_rec[fn] = rec_t
            p = fresh_name("n")
            e_body = dict(e_rec)
            e_body[p] = "Int"
            base = gen_typed(ret_t, e_body, depth - 1)
            if ret_t == "Int":
                step = f"({fn} ({p} - 1) + 1)"
            else:
                step = f"({fn} ({p} - 1))"
            body_res = gen_typed(target_ty, e_rec, depth - 1)
            return (
                f"(let rec {fn} : {ty_str(rec_t)} = /{p} -> "
                f"if {p} < 1 then {base} else {step} in {body_res})"
            )
        return gen_typed(target_ty, env, 0)

    stats = {"val": 0, "RuntimeError": 0}
    for i in range(2000):
        tgt = rand_ty(2)
        src = gen_typed(tgt, {}, rng.randint(1, 4))
        data = src.encode("ascii")
        ast = parse(tokenize(data))
        try:
            exp = ref_run(ast)
        except RefTypeErr:
            raise AssertionError(f"Generated program failed ref typecheck:\n  {src}")
        except RefRunErr:
            exp = "RuntimeError"
        got, _ = run_source(data)
        if got != exp:
            raise AssertionError(
                f"Typed fuzz mismatch #{i}:\n  src={src}\n  got={got}\n  exp={exp}"
            )
        if exp == "RuntimeError":
            stats["RuntimeError"] += 1
        else:
            stats["val"] += 1
    print(f"  [PASS] 2,000 well-typed higher-order/curried fuzz programs ({stats})")


